def parse_row(line: str) -> list[str]:
    result = []
    current = []
    in_quotes = False
    for char in line:
        if char == '"':
            in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            result.append("".join(current))
            current = []
        else:
            current.append(char)
    result.append("".join(current))
    return result
```

