def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = set()
    result = []
    for row in rows:
        if key not in row:
            result.append(row)
        else:
            if row[key] not in seen:
                seen.add(row[key])
                result.append(row)
    return result
```

